import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

// Desktop outputs generated by the pinned Tauri CLI. Never trust a source-only
// stamp: a missing or manually replaced output can otherwise look current.
export const ICON_FILES = [
  "32x32.png",
  "64x64.png",
  "128x128.png",
  "128x128@2x.png",
  "icon.png",
  "icon.ico",
  "icon.icns",
  "StoreLogo.png",
  "Square30x30Logo.png",
  "Square44x44Logo.png",
  "Square71x71Logo.png",
  "Square89x89Logo.png",
  "Square107x107Logo.png",
  "Square142x142Logo.png",
  "Square150x150Logo.png",
  "Square284x284Logo.png",
  "Square310x310Logo.png",
];
export function iconManifest(dir) {
  const files = {};
  for (const name of ICON_FILES) {
    const file = path.join(dir, name);
    if (!existsSync(file)) return null;
    files[name] = createHash("sha256").update(readFileSync(file)).digest("hex");
  }
  return `${JSON.stringify({ version: 1, files }, null, 2)}\n`;
}
